package com.gestordevendas.api.food; import com.gestordevendas.api.company.Company; import jakarta.persistence.*; import java.math.BigDecimal; import java.util.*;
@Entity @Table(name="snacks") public class Snack { @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="company_id") private Company company; @Column(nullable=false) private String name; @Column(nullable=false) private BigDecimal price; @ElementCollection @CollectionTable(name="snack_ingredients",joinColumns=@JoinColumn(name="snack_id")) @Column(name="ingredient") private List<String> ingredients=new ArrayList<>(); @ElementCollection @CollectionTable(name="snack_additionals",joinColumns=@JoinColumn(name="snack_id")) private List<SnackAdditional> additionals=new ArrayList<>(); protected Snack(){} public static Snack create(Company c,String n,BigDecimal p,List<String> i,List<SnackAdditional> a){var x=new Snack();x.id=UUID.randomUUID();x.company=c;x.update(n,p,i,a);return x;} public void update(String n,BigDecimal p,List<String> i,List<SnackAdditional>a){name=n;price=p;ingredients.clear();ingredients.addAll(i);additionals.clear();additionals.addAll(a);} public UUID getId(){return id;} public String getName(){return name;} public BigDecimal getPrice(){return price;} public List<String> getIngredients(){return ingredients;} public List<SnackAdditional> getAdditionals(){return additionals;} }